const company = $('Webhook').item.json.body.company;
const jobId = $('Webhook').item.json.body.jobId;

const systemPrompt = 'You are an AI research orchestrator. Given a company name, produce a JSON research plan with exactly 3 fields: overview_query, news_query, risk_query. Each is a concise, targeted search query string. Respond with only valid JSON — no markdown, no explanation.';

const requestBody = {
  model: 'gpt-4o',
  max_tokens: 300,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: 'Company to research: ' + company }
  ]
};

return [{ json: { company, jobId, requestBody: JSON.stringify(requestBody) } }];

const company = $('Prepare Orchestrator Body').item.json.company;
const jobId = $('Prepare Orchestrator Body').item.json.jobId;
const content = $('Orchestrator LLM').item.json.choices[0].message.content;

let plan;
try {
  const match = content.match(/\{[\s\S]*\}/);
  plan = match ? JSON.parse(match[0]) : null;
} catch(e) { plan = null; }

return [{
  json: {
    company,
    jobId,
    overview_query: plan?.overview_query || (company + ' company overview business model products services'),
    news_query: plan?.news_query || (company + ' latest news 2025'),
    risk_query: plan?.risk_query || (company + ' AI security risk data privacy compliance breach')
  }
}];

const plan = $('Parse Research Plan').item.json;
const overviewResults = $('Exa Research Search').item.json.results || [];
const newsResults = $('Exa News Search').item.json.results || [];

const overviewText = overviewResults.slice(0, 3).map(r => r.title + ': ' + (r.text || '').slice(0, 400)).join('\n\n');
const newsText = newsResults.slice(0, 3).map(r => r.title + ' (' + (r.publishedDate || 'recent') + '): ' + (r.text || '').slice(0, 300)).join('\n\n');

const systemPrompt = `You are an AI security risk analyst at Varonis. Analyze the company research and identify the following — be specific and concise, max 3 bullets per section:

**AI Adoption Signals** — What AI tools, vendors, or models they use or plan to use
**Data Security Risks** — Sensitive data exposure, compliance gaps, breach history
**Shadow AI Risks** — Unauthorized or unmonitored AI tool usage indicators
**Atlas Opportunity** — Why Varonis Atlas AI Security Platform fits their situation`;

const userContent = `Company: ${plan.company}\n\nOVERVIEW RESEARCH:\n${overviewText}\n\nRECENT NEWS:\n${newsText}`;

const requestBody = {
  model: 'gpt-4o',
  max_tokens: 700,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent }
  ]
};

return [{
  json: {
    company: plan.company,
    jobId: plan.jobId,
    overviewResults: overviewResults.slice(0, 4).map(r => ({ title: r.title, url: r.url })),
    newsResults: newsResults.slice(0, 4).map(r => ({ title: r.title, url: r.url, date: r.publishedDate })),
    overviewText,
    newsText,
    requestBody: JSON.stringify(requestBody)
  }
}];

const prep = $('Prepare Risk Body').item.json;
const riskAnalysis = $('Risk Analyst LLM').item.json.choices[0].message.content;

const systemPrompt = `You are an expert AI research assistant preparing a pre-meeting briefing for a Varonis sales engineer. Using the research provided, write a structured, actionable briefing in markdown.

Use these exact sections:
## Company Overview
## Recent Developments  
## AI & Data Security Risk Profile
## Recommended Atlas Demo Angle
## Suggested Discovery Questions

Be specific, concise, and tailored to help the SE have a compelling conversation about AI security risks.`;

const userContent = `Company: ${prep.company}\n\nOVERVIEW:\n${prep.overviewText}\n\nRECENT NEWS:\n${prep.newsText}\n\nRISK ANALYSIS:\n${riskAnalysis}`;

const requestBody = {
  model: 'gpt-4o',
  max_tokens: 1500,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent }
  ]
};

return [{
  json: {
    company: prep.company,
    jobId: prep.jobId,
    overviewResults: prep.overviewResults,
    newsResults: prep.newsResults,
    riskAnalysis,
    requestBody: JSON.stringify(requestBody)
  }
}];

const prep = $('Prepare Report Body').item.json;
const report = $('Report Agent LLM').item.json.choices[0].message.content;

const sources = [
  ...prep.overviewResults.map(r => ({ ...r, category: 'Overview' })),
  ...prep.newsResults.map(r => ({ ...r, category: 'News' }))
];

const result = {
  status: 'done',
  company: prep.company,
  jobId: prep.jobId,
  report,
  risk_analysis: prep.riskAnalysis,
  sources,
  atlas_audit: {
    llm_calls: 3,
    tool_calls: 2,
    agents: ['Orchestrator Agent', 'Research Agent (Exa)', 'News Agent (Exa)', 'Risk Analyst Agent', 'Report Agent'],
    gateway: 'Atlas AI Gateway',
    policy_enforced: true
  },
  completed_at: new Date().toISOString()
};

return [{
  json: {
    key: 'mcp:' + prep.jobId,
    value: JSON.stringify(result),
    pipeline: JSON.stringify([["SET", 'mcp:' + prep.jobId, JSON.stringify(result), "EX", 86400]])
  }
}];
